// Applied to every Vite page, including pages generated by the localization plugin.
// The first-party script makes the consent choice before it loads Google's tag.
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'

export function analyticsConsentPlugin() {
  const versioned = name => {
    const content = readFileSync(new URL(`../public/${name}`, import.meta.url))
    return `/${name}?v=${createHash('sha256').update(content).digest('hex').slice(0, 12)}`
  }
  const scriptUrl = versioned('analytics-consent.js')
  const styleUrl = versioned('analytics-consent.css')
  return {
    name: 'meerkatta-analytics-consent',
    transformIndexHtml: {
      order: 'post',
      handler(_html, context) {
        // Checkout URLs can contain an email prefill and should never be sent
        // to analytics, even if the visitor opted into general site analytics.
        if (/^\/(?:pay|padsandbox)(?:\/|$)/.test(context.path)) return []
        return [
          { tag: 'link', attrs: { rel: 'stylesheet', href: styleUrl }, injectTo: 'head' },
          { tag: 'script', attrs: { src: scriptUrl, defer: true }, injectTo: 'head' },
        ]
      },
    },
  }
}
